<?php
declare(strict_types=1);
use Karoor\Core\Helpers;
$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($id===false||$id===null){http_response_code(404);exit('Salary slip not found.');}$companyId=(int)$currentUser['company_id'];$payroll=$database->fetchOne('SELECT p.*,e.employee_number,e.full_name employee_name,e.position,e.currency_code,d.name department_name,co.name company_name,co.address_line1,co.city,co.phone company_phone,co.email company_email,co.logo_path FROM payroll p INNER JOIN employees e ON e.id=p.employee_id LEFT JOIN departments d ON d.id=e.department_id INNER JOIN companies co ON co.id=p.company_id WHERE p.id=:id AND p.company_id=:company AND p.deleted_at IS NULL',['id'=>$id,'company'=>$companyId]);if($payroll===null){http_response_code(404);exit('Salary slip not found.');}$items=$database->fetchAll('SELECT name,component_type,amount,notes FROM payroll_items WHERE payroll_id=:id ORDER BY FIELD(component_type,\'ALLOWANCE\',\'OVERTIME\',\'BONUS\',\'DEDUCTION\',\'TAX\'),id',['id'=>$id]);$earnings=array_values(array_filter($items,static fn($i)=>in_array($i['component_type'],['ALLOWANCE','OVERTIME','BONUS'],true)));$deductions=array_values(array_filter($items,static fn($i)=>in_array($i['component_type'],['DEDUCTION','TAX'],true)));
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payslip · <?= Helpers::escape($payroll['employee_name']) ?></title><link rel="stylesheet" href="<?= Helpers::escape(Helpers::appPath($config,'/assets/css/print.css')) ?>"></head><body class="print-document invoice-document"><div class="print-toolbar"><button type="button" data-print-trigger>Print payslip</button><a href="<?= Helpers::escape(Helpers::appPath($config,'/hrm?view=payroll')) ?>">Back to payroll</a></div><main class="invoice"><header class="invoice-header"><div class="print-brand"><?php if($payroll['logo_path']):?><img src="<?= Helpers::escape(Helpers::appPath($config,'/'.$payroll['logo_path'])) ?>" alt=""><?php endif;?><h1><?= Helpers::escape($payroll['company_name']) ?></h1><p><?= Helpers::escape(trim(($payroll['address_line1']??'').' '.($payroll['city']??''))) ?><br><?= Helpers::escape($payroll['company_phone']) ?></p></div><div><span class="document-label">SALARY SLIP</span><h2><?= Helpers::escape(date('F Y',strtotime($payroll['payroll_month']))) ?></h2><p><span class="status"><?= Helpers::escape($payroll['status']) ?></span></p></div></header><section class="invoice-parties"><div><small>EMPLOYEE</small><strong><?= Helpers::escape($payroll['employee_name']) ?></strong><span><?= Helpers::escape($payroll['employee_number']) ?></span><span><?= Helpers::escape($payroll['position']) ?></span></div><div><small>DEPARTMENT</small><strong><?= Helpers::escape($payroll['department_name']??'Not assigned') ?></strong><span>Payroll month: <?= Helpers::escape($payroll['payroll_month']) ?></span><?php if($payroll['paid_at']):?><span>Paid: <?= Helpers::escape(date('F j, Y',strtotime($payroll['paid_at']))) ?></span><?php endif;?></div></section><div class="payslip-grid"><section><h3>Earnings</h3><table><tbody><tr><td>Basic salary</td><td class="num"><?= number_format((float)$payroll['basic_salary'],2) ?></td></tr><?php foreach($earnings as$item):?><tr><td><?= Helpers::escape($item['name']) ?></td><td class="num"><?= number_format((float)$item['amount'],2) ?></td></tr><?php endforeach;?><tr class="total-row"><td>Gross salary</td><td class="num"><?= number_format((float)$payroll['gross_salary'],2) ?></td></tr></tbody></table></section><section><h3>Deductions</h3><table><tbody><?php if(!$deductions):?><tr><td>No deductions</td><td class="num">0.00</td></tr><?php endif;?><?php foreach($deductions as$item):?><tr><td><?= Helpers::escape($item['name']) ?></td><td class="num"><?= number_format((float)$item['amount'],2) ?></td></tr><?php endforeach;?><tr class="total-row"><td>Total deductions</td><td class="num"><?= number_format((float)$payroll['total_deductions']+(float)$payroll['total_tax'],2) ?></td></tr></tbody></table></section></div><div class="net-pay"><span>NET PAY</span><strong><?= Helpers::escape($payroll['currency_code']) ?> <?= number_format((float)$payroll['net_salary'],2) ?></strong></div><?php if($payroll['notes']):?><section class="notes"><h3>Notes</h3><p><?= Helpers::escape($payroll['notes']) ?></p></section><?php endif;?><footer>This salary slip is generated from the approved Karoor ERP payroll ledger.</footer></main><script src="<?= Helpers::escape(Helpers::appPath($config,'/assets/js/print.js')) ?>" defer></script></body></html>
